private fun ui(block:()->Unit)=Handler(Looper.getMainLooper()).post(block)
private fun prefs(c:Context)=c.getSharedPreferences(PREFS,Context.MODE_PRIVATE)
private fun saveSession(c:Context,s:RWSession?){val e=prefs(c).edit();if(s==null)e.remove(A_ACCESS).remove(A_REFRESH) else e.putString(A_ACCESS,s.access).putString(A_REFRESH,s.refresh);e.apply()}
private fun loadSession(c:Context):RWSession?{val p=prefs(c);val a=p.getString(A_ACCESS,"")?:"";val r=p.getString(A_REFRESH,"")?:"";return if(a.isBlank())null else RWSession(a,r)}
private fun conn(url:String,token:String?=null):HttpURLConnection{val c=URL(url).openConnection() as HttpURLConnection;c.setRequestProperty("apikey",SB_KEY);if(!token.isNullOrBlank())c.setRequestProperty("Authorization","Bearer $token");return c}
private fun getArray(path:String,token:String?=null):JSONArray{val c=conn("$SB_URL/rest/v1/$path",token);val code=c.responseCode;if(code !in 200..299){val m=c.errorStream?.bufferedReader()?.use{it.readText()}.orEmpty();c.disconnect();throw IllegalStateException(m)};val a=JSONArray(c.inputStream.bufferedReader().use{it.readText()});c.disconnect();return a}
private fun writeJson(path:String,method:String,payload:JSONObject,token:String?=null):Boolean{val c=conn("$SB_URL/rest/v1/$path",token);c.requestMethod=method;c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Prefer","return=minimal");c.doOutput=true;c.outputStream.use{it.write(payload.toString().toByteArray())};val ok=c.responseCode in 200..299;c.disconnect();return ok}
private fun postPublic(table:String,payload:JSONObject,onDone:(Boolean)->Unit){Thread{var ok=false;try{ok=writeJson(table,"POST",payload)}catch(_:Exception){};ui{onDone(ok)}}.start()}

private fun login(email:String,password:String,onDone:(RWSession?,String)->Unit){Thread{var s:RWSession?=null;var msg="Login failed.";try{val c=conn("$SB_URL/auth/v1/token?grant_type=password");c.requestMethod="POST";c.setRequestProperty("Content-Type","application/json");c.doOutput=true;c.outputStream.use{it.write(JSONObject().put("email",email).put("password",password).toString().toByteArray())};val code=c.responseCode;val body=if(code in 200..299)c.inputStream.bufferedReader().use{it.readText()} else c.errorStream?.bufferedReader()?.use{it.readText()}.orEmpty();if(code in 200..299){val j=JSONObject(body);s=RWSession(j.optString("access_token"),j.optString("refresh_token"));msg="Login successful."}else msg="Check email/password.";c.disconnect()}catch(_:Exception){msg="Unable to connect."};ui{onDone(s,msg)}}.start()}
private fun forgot(email:String,onDone:(Boolean)->Unit){Thread{var ok=false;try{val c=conn("$SB_URL/auth/v1/recover");c.requestMethod="POST";c.setRequestProperty("Content-Type","application/json");c.doOutput=true;c.outputStream.use{it.write(JSONObject().put("email",email).toString().toByteArray())};ok=c.responseCode in 200..299;c.disconnect()}catch(_:Exception){};ui{onDone(ok)}}.start()}

private fun compressedJpeg(context:Context,uri:Uri):ByteArray?{return try{val original=context.contentResolver.openInputStream(uri)?.use{BitmapFactory.decodeStream(it)}?:return null;val max=1600;val ratio=minOf(1f,max.toFloat()/maxOf(original.width,original.height).toFloat());val scaled=if(ratio<1f)Bitmap.createScaledBitmap(original,(original.width*ratio).toInt(),(original.height*ratio).toInt(),true) else original;val out=ByteArrayOutputStream();scaled.compress(Bitmap.CompressFormat.JPEG,82,out);if(scaled!==original)scaled.recycle();original.recycle();out.toByteArray()}catch(_:Exception){null}}
private fun uploadImage(context:Context,token:String,bucket:String,uri:Uri,onDone:(String?,String)->Unit){Thread{var publicUrl:String?=null;var msg="Photo upload failed.";try{val bytes=compressedJpeg(context,uri)?:throw IllegalStateException("Cannot read image");if(bytes.size>8_000_000)throw IllegalStateException("Photo is too large");val name="${System.currentTimeMillis()}_${(1000..9999).random()}.jpg";val enc=URLEncoder.encode(name,"UTF-8").replace("+","%20");val c=conn("$SB_URL/storage/v1/object/$bucket/$enc",token);c.requestMethod="POST";c.setRequestProperty("Content-Type","image/jpeg");c.setRequestProperty("x-upsert","true");c.doOutput=true;c.outputStream.use{it.write(bytes)};val code=c.responseCode;val body=if(code in 200..299)"" else c.errorStream?.bufferedReader()?.use{it.readText()}.orEmpty();if(code in 200..299){publicUrl="$SB_URL/storage/v1/object/public/$bucket/$enc";msg="Photo uploaded."}else msg="Photo upload failed (${code}). ${body.take(120)}";c.disconnect()}catch(e:Exception){msg="Photo upload failed: ${e.message?:"unknown error"}"};ui{onDone(publicUrl,msg)}}.start()}

private fun fetchProducts(category:String?=null,onDone:(List<RWProduct>)->Unit){Thread{val out=mutableListOf<RWProduct>();try{val filter=if(category.isNullOrBlank())"" else "&category=eq.${URLEncoder.encode(category,"UTF-8")}";val a=getArray("products?select=id,name,category,description,price,image_url&is_active=eq.true$filter&order=created_at.desc");for(i in 0 until a.length()){val x=a.getJSONObject(i);out+=RWProduct(x.optString("id"),x.optString("name"),x.optString("category"),x.optString("description"),x.optDouble("price"),x.optString("image_url").takeIf{it.isNotBlank()&&it!="null"})}}catch(_:Exception){};ui{onDone(out)}}.start()}
private fun fetchGallery(onDone:(List<RWGallery>)->Unit){Thread{val out=mutableListOf<RWGallery>();try{val a=getArray("gallery?select=id,title,gallery_type,image_url,caption&is_active=eq.true&order=created_at.desc");for(i in 0 until a.length()){val x=a.getJSONObject(i);out+=RWGallery(x.optString("id"),x.optString("title"),x.optString("gallery_type"),x.optString("image_url"),x.optString("caption").takeIf{it.isNotBlank()&&it!="null"})}}catch(_:Exception){};ui{onDone(out)}}.start()}
private fun fetchContact(key:String,onDone:(RWContact?)->Unit){Thread{var r:RWContact?=null;try{val a=getArray("service_contacts?select=service_key,contact_name,phone,email,whatsapp&service_key=eq.${URLEncoder.encode(key,"UTF-8")}&limit=1");if(a.length()>0){val x=a.getJSONObject(0);r=RWContact(x.optString("service_key"),x.optString("contact_name"),x.optString("phone"),x.optString("email"),x.optString("whatsapp"))}}catch(_:Exception){};ui{onDone(r)}}.start()}
private fun fetchShopMasters(onDone:(List<String>)->Unit){Thread{val out=mutableListOf<String>();try{val a=getArray("masters?select=name&master_type=eq.shop&is_active=eq.true&order=name.asc");for(i in 0 until a.length())out+=a.getJSONObject(i).optString("name")}catch(_:Exception){};ui{onDone(if(out.isEmpty())baseServices.last().options else out.distinct())}}.start()}

