(12.dp)){Text("Add Master",fontWeight=FontWeight.Bold);SimpleDropdown("Master Type",masterType,listOf("shop","service","gallery")){masterType=it};OutlinedTextField(masterName,{masterName=it},label={Text("Master name")},modifier=Modifier.fillMaxWidth());Button(onClick={if(masterName.isBlank())msg="Enter master name." else Thread{val ok=try{writeJson("masters","POST",JSONObject().put("master_type",masterType).put("name",masterName).put("is_active",true),session.access)}catch(_:Exception){false};ui{msg=if(ok)"✅ Master added." else "Could not add master.";if(ok){masterName="";fetchShopMasters{categories=it}}}}.start()},modifier=Modifier.fillMaxWidth()){Text("Add Master")}}};Spacer(Modifier.height(12.dp));Text("PRODUCT MANAGEMENT",color=Purple,fontWeight=FontWeight.Bold);Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){OutlinedTextField(productName,{productName=it},label={Text("Product name")},modifier=Modifier.fillMaxWidth());SimpleDropdown("Category",productCategory,categories){productCategory=it};OutlinedTextField(price,{price=it},label={Text("Price (INR)")},modifier=Modifier.fillMaxWidth());OutlinedTextField(description,{description=it},label={Text("Description")},modifier=Modifier.fillMaxWidth());OutlinedButton(onClick={pp.launch("image/*")},modifier=Modifier.fillMaxWidth()){Text(if(productPhoto==null)"📷 Choose Product Photo" else "✅ Product Photo Selected")};Button(onClick={val uri=productPhoto;val amount=price.toDoubleOrNull();if(productName.isBlank()||uri==null||amount==null)msg="Enter product, valid price and select photo." else{msg="Compressing and uploading photo...";uploadImage(context,session.access,"product-gallery",uri){url,m->if(url==null)msg=m else Thread{val ok=try{writeJson("products","POST",JSONObject().put("name",productName).put("category",productCategory).put("description",description).put("price",amount).put("currency","INR").put("image_url",url).put("is_free",amount==0.0).put("is_active",true),session.access)}catch(_:Exception){false};ui{msg=if(ok)"✅ Product added with photo." else "Photo uploaded but product save failed.";if(ok){productName="";price="";description="";productPhoto=null}}}.start()}}}},modifier=Modifier.fillMaxWidth()){Text("Add Product")}}};Spacer(Modifier.height(12.dp));Text("PHOTO GALLERY",color=Purple,fontWeight=FontWeight.Bold);Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("Upload event, activity or achievement photos",fontWeight=FontWeight.Bold);OutlinedTextField(galleryTitle,{galleryTitle=it},label={Text("Title")},modifier=Modifier.fillMaxWidth());SimpleDropdown("Type",galleryType,listOf("Event","Activity","Achievement","Other")){galleryType=it};OutlinedTextField(galleryCaption,{galleryCaption=it},label={Text("Caption (optional)")},modifier=Modifier.fillMaxWidth());OutlinedButton(onClick={gp.launch("image/*")},modifier=Modifier.fillMaxWidth()){Text(if(galleryPhoto==null)"📸 Choose Gallery Photo" else "✅ Gallery Photo Selected")};Button(onClick={val uri=galleryPhoto;if(galleryTitle.isBlank()||uri==null)msg="Enter title and select a gallery photo." else{msg="Uploading gallery photo...";uploadImage(context,session.access,"gallery",uri){url,m->if(url==null)msg=m else Thread{val ok=try{writeJson("gallery","POST",JSONObject().put("title",galleryTitle).put("gallery_type",galleryType).put("caption",galleryCaption).put("image_url",url).put("is_active",true),session.access)}catch(_:Exception){false};ui{msg=if(ok)"✅ Gallery photo published." else "Photo uploaded but gallery save failed.";if(ok){galleryTitle="";galleryCaption="";galleryPhoto=null;loadGallery()}}}.start()}}}},modifier=Modifier.fillMaxWidth()){Text("Add Gallery Photo")};galleryRows.take(6).forEach{g->Card(Modifier.fillMaxWidth().padding(vertical=4.dp)){Column(Modifier.padding(8.dp)){RemoteImageV2(g.imageUrl);Text(g.title,fontWeight=FontWeight.Bold);Text(g.type)}}}}};Spacer(Modifier.height(12.dp));Text("SERVICE CONTACT MASTER",color=Purple,fontWeight=FontWeight.Bold);Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){SimpleDropdown("Service",service.title,baseServices.map{it.title}){name->service=baseServices.first{it.title==name}};OutlinedTextField(cn,{cn=it},label={Text("Contact name")},modifier=Modifier.fillMaxWidth());OutlinedTextField(cp,{cp=it},label={Text("Phone")},modifier=Modifier.fillMaxWidth());OutlinedTextField(ce,{ce=it},label={Text("Email")},modifier=Modifier.fillMaxWidth());OutlinedTextField(cw,{cw=it},label={Text("WhatsApp")},modifier=Modifier.fillMaxWidth());Button(onClick={Thread{val payload=JSONObject().put("service_key",service.id).put("service_name",service.title).put("contact_name",cn).put("phone",cp).put("email",ce).put("whatsapp",cw).put("is_active",true);val ok=try{val c=conn("$SB_URL/rest/v1/service_contacts?on_conflict=service_key",session.access);c.requestMethod="POST";c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Prefer","resolution=merge-duplicates,return=minimal");c.doOutput=true;c.outputStream.use{it.write(payload.toString().toByteArray())};val o=c.responseCode in 200..299;c.disconnect();o}catch(_:Exception){false};ui{msg=if(ok)"✅ ${service.title} contact saved." else "Could not save contact."}}.start()},modifier=Modifier.fillMaxWidth()){Text("Save Service Contact")}}};Spacer(Modifier.height(8.dp));Text(msg);OutlinedButton(onClick=logout,modifier=Modifier.fillMaxWidth()){Text("Logout")};Spacer(Modifier.height(30.dp))}}

@Composable fun SimpleDropdown(label:String,value:String,options:List<String>,onPick:(String)->Unit){var expanded by remember{mutableStateOf(false)};Box(Modifier.fillMaxWidth()){OutlinedButton(onClick={expanded=true},modifier=Modifier.fillMaxWidth()){Text("$label: $value")};DropdownMenu(expanded,onDismissRequest={expanded=false}){options.distinct().forEach{o->DropdownMenuItem(text={Text(o)},onClick={onPick(o);expanded=false})}}}}
